CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN('customer','driver','admin')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS driver_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,id_no TEXT,vehicle TEXT,area TEXT NOT NULL DEFAULT 'البرك',iban TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders (id BIGSERIAL PRIMARY KEY,customer_id UUID NOT NULL REFERENCES users(id),service_type TEXT NOT NULL,store_name TEXT,items TEXT NOT NULL,note TEXT,pickup_lat DOUBLE PRECISION NOT NULL,pickup_lng DOUBLE PRECISION NOT NULL,dropoff_lat DOUBLE PRECISION NOT NULL,dropoff_lng DOUBLE PRECISION NOT NULL,distance_km NUMERIC(10,2),delivery_fee NUMERIC(10,2) NOT NULL DEFAULT 0,offer_price NUMERIC(10,2),payment_method TEXT NOT NULL DEFAULT 'cash' CHECK(payment_method IN('cash','online')),status TEXT NOT NULL DEFAULT 'pending_offers' CHECK(status IN('pending_offers','accepted','in_delivery','delivered','cancelled')),driver_id UUID REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS driver_offers (id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,driver_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,price NUMERIC(10,2) NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','rejected')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(order_id,driver_id));
CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id); CREATE INDEX IF NOT EXISTS idx_orders_driver ON orders(driver_id); CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status); CREATE INDEX IF NOT EXISTS idx_offers_driver ON driver_offers(driver_id);
